import{_ as e,o as s,c as a,a5 as o}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"Bottom LED — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/led-bottom.md","filePath":"software/sdk/python/led-bottom.md","lastUpdated":1793350928000}'),i={name:"software/sdk/python/led-bottom.md"};function n(l,t,h,r,p,d){return s(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="bottom-led-—-python-example" tabindex="-1">Bottom LED — Python Example <a class="header-anchor" href="#bottom-led-—-python-example" aria-label="Permalink to &quot;Bottom LED — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_led_bottom.py</code></p><p>Python port of the C++ <a href="/RBQ/nightly/software/sdk/cpp/led-bottom.html">Bottom LED</a>. Sets the two <strong>status LEDs under the body</strong> by publishing one <code>LedBottom_</code> message on <code>rt/rbq/cmd/led_bottom</code>, then prints the 1 Hz <code>LedBottomState_</code> the robot reports on <code>rt/rbq/led_bottom</code>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>side mode r g b on_ms off_ms count</code> from the command line.</li><li>Calls <code>ChannelFactoryInitialize(0, interface)</code>, then creates <code>ChannelPublisher(&quot;rt/rbq/cmd/led_bottom&quot;, LedBottom_)</code> and <code>ChannelSubscriber(&quot;rt/rbq/led_bottom&quot;, LedBottomState_)</code> with a handler that keeps the latest state.</li><li>Waits ~0.5 s for DDS discovery, fills the <code>LedBottom_</code> message and publishes <strong>once</strong>.</li><li>Waits ~2.5 s for the IF board to apply the setting and report it, prints the last <code>LedBottomState_</code> received and exits.</li></ol><p>The on-robot <strong>Network</strong> process checks the ranges (the same check as <code>PUT /api/led/bottom</code>), Motion sends the setting to the IF board over CAN FD, and the board&#39;s once-a-second report comes back on <code>rt/rbq/led_bottom</code>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> importable — see <a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>The robot stack running on the same DDS interface.</li><li><strong>A CAN FD robot.</strong> On other robots Network rejects the command and publishes no state, so the example prints <code>no state on rt/rbq/led_bottom</code>. In the simulator Motion stands in for the IF board and MuJoCo shows the two LEDs under the body, so the example works there too.</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_led_bottom.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface] [side] [mode] [r] [g] [b] [on_ms] [off_ms] [count]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Both LEDs steady blue (the defaults) — the interface always comes first:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_led_bottom.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Right LED blinking red, 0.5 s on / 0.5 s off, forever:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_led_bottom.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> right</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 255</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Both LEDs off:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_led_bottom.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> both</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span></code></pre></div><p>All arguments are positional, so <strong>the interface must be the first argument</strong>.</p><p>Arguments and defaults are identical to the <a href="/RBQ/nightly/software/sdk/cpp/led-bottom.html#run">C++ version</a>. Use the interface that reaches the robot — <code>lo</code> when running on the robot PC, your NIC from another host.</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_led_bottom] published: side=right mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0</span></span>
<span class="line"><span>[rbq_led_bottom] state: age_ms=312 configured=1 if_fw=2026100701</span></span>
<span class="line"><span>  right: mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0 actual=255,0,0 lpf_w=0.6</span></span>
<span class="line"><span>  left: mode=on rgb=0,0,255 on_ms=0 off_ms=0 count=0 actual=0,0,255 lpf_w=0.4</span></span></code></pre></div><p>Values depend on the robot. <code>actual</code> is the last output after the IF board&#39;s power limit, and <code>limited</code> appears when that limit reduced the output within the last second.</p>`,15)])])}const m=e(i,[["render",n]]);export{k as __pageData,m as default};
